const CSS_550C = "\n  :host{--amber:#e8a020;--amber-b:#ffc043;--amber-d:#8a5e10;--amber-fade:rgba(232,160,32,.35);--text:#d8c090;--text-dim:#8a7248;--text-faint:#4a3f28;--bg:#050403;--bg-panel:#0a0805;--bg-win:#0d0a06;--red:#e05030;--red-b:#ff7050;--green:#b8c840;--cyan:#4fd1c5;}\n  *{box-sizing:border-box;margin:0;padding:0;}\n  :host{height:100%;}\n  :host{background:var(--bg);color:var(--text);font-family:\"SF Mono\",Menlo,Monaco,Consolas,\"Courier New\",monospace;font-size:12px;line-height:1.55;overflow:hidden;-webkit-font-smoothing:antialiased;}\n  :host::before{content:\"\";position:fixed;inset:0;pointer-events:none;z-index:900;background:repeating-linear-gradient(to bottom,rgba(232,160,32,.04) 0,rgba(232,160,32,.04) 1px,transparent 1px,transparent 3px);}\n  :host::after{content:\"\";position:fixed;inset:0;pointer-events:none;z-index:899;background:radial-gradient(ellipse at center,transparent 45%,rgba(0,0,0,.85) 100%);}\n\n  /* ===== 开机动画 ===== */\n  #boot{position:fixed;inset:0;z-index:2000;background:#000;transition:opacity .55s ease;}\n  #boot.fade{opacity:0;pointer-events:none;}\n  #boot::before{content:\"\";position:fixed;inset:0;background:repeating-linear-gradient(to bottom,rgba(255,255,255,.025) 0,rgba(255,255,255,.025) 1px,transparent 1px,transparent 4px);pointer-events:none;z-index:2;}\n  .boot-stage{position:relative;width:100%;height:100%;display:flex;align-items:center;justify-content:center;z-index:1;}\n  .boot-stage svg{width:min(680px,90vw);height:auto;overflow:visible;}\n  .white{fill:#fff;stroke:none;}\n  .red{fill:#ff2d2d;stroke:none;}\n  #logo.finished .white{animation:glowW 2.6s ease-in-out infinite;}\n  #logo.finished .red{animation:glowR 2.6s ease-in-out infinite;}\n  @keyframes glowW{0%,100%{filter:drop-shadow(0 0 6px rgba(255,255,255,.5));}50%{filter:drop-shadow(0 0 14px rgba(255,255,255,.9));}}\n  @keyframes glowR{0%,100%{filter:drop-shadow(0 0 8px rgba(255,45,45,.6));}50%{filter:drop-shadow(0 0 18px rgba(255,45,45,1));}}\n  .boot-text{position:absolute;left:0;right:0;bottom:12%;text-align:center;color:rgba(255,255,255,.35);font-family:\"Courier New\",Consolas,monospace;font-size:12px;letter-spacing:.4em;padding-left:.4em;opacity:0;}\n  .boot-text.show{animation:fadeIn .6s ease forwards;}\n  .boot-text .cursor{display:inline-block;width:6px;height:12px;background:#fff;margin-left:8px;vertical-align:-2px;animation:blink 1s steps(1) infinite;}\n  @keyframes blink{0%,49%{opacity:1}50%,100%{opacity:0}}\n  @keyframes fadeIn{to{opacity:1;}}\n\n  /* ===== 主界面 ===== */\n  #app{height:100%;display:grid;grid-template-rows:26px 1fr 24px;padding:6px;gap:5px;opacity:0;transition:opacity .5s ease;}\n  #app.visible{opacity:1;}\n  #hud-top{display:flex;align-items:center;gap:14px;padding:0 10px;background:linear-gradient(180deg,#141008,#0a0805);border:1px solid var(--amber-d);font-size:10.5px;letter-spacing:.15em;text-transform:uppercase;color:var(--amber);}\n  #hud-top .brand{font-weight:700;letter-spacing:.2em;text-shadow:0 0 8px var(--amber-fade);}\n  #hud-top .sep{color:var(--text-faint);}\n  #hud-top .item{color:var(--text-dim);}\n  #hud-top .item b{color:var(--amber);font-weight:400;}\n  #hud-top .spacer{flex:1;}\n  #hud-top .live{color:var(--red);animation:blink 1s steps(1) infinite;}\n  #workspace{display:grid;grid-template-columns:1fr 1.7fr 1fr;grid-template-rows:1.1fr 1fr;grid-template-areas:\"tele main code\" \"tele main node\";gap:5px;min-height:0;}\n  .w{position:relative;display:flex;flex-direction:column;overflow:hidden;background:var(--bg-panel);border:1px solid var(--amber-d);box-shadow:inset 0 0 30px rgba(232,160,32,.03);}\n  .w::before,.w::after{content:\"\";position:absolute;width:8px;height:8px;border-color:var(--amber);z-index:5;pointer-events:none;}\n  .w::before{top:-1px;left:-1px;border-top:2px solid;border-left:2px solid;}\n  .w::after{bottom:-1px;right:-1px;border-bottom:2px solid;border-right:2px solid;}\n  #w-tele{grid-area:tele;}#w-main{grid-area:main;}#w-code{grid-area:code;}#w-node{grid-area:node;}\n  .w-head{flex:none;display:flex;align-items:center;gap:8px;padding:4px 8px;background:linear-gradient(180deg,#161006,#0a0805);border-bottom:1px solid var(--amber-d);font-size:9.5px;letter-spacing:.2em;text-transform:uppercase;color:var(--amber);}\n  .w-head .led{width:6px;height:6px;border-radius:50%;background:var(--green);box-shadow:0 0 6px var(--green);animation:pulse 1.2s infinite;}\n  .w-head .led.red{background:var(--red);box-shadow:0 0 6px var(--red);}\n  @keyframes pulse{0%,100%{opacity:1}50%{opacity:.25}}\n  .w-head .tag{margin-left:auto;color:var(--text-faint);font-size:9px;letter-spacing:.1em;}\n  .w-body{flex:1;overflow:auto;padding:6px 8px;min-height:0;font-size:11px;line-height:1.55;scrollbar-width:thin;scrollbar-color:rgba(232,160,32,.3) transparent;}\n  .w-body::-webkit-scrollbar{width:5px;height:5px;}\n  .w-body::-webkit-scrollbar-thumb{background:rgba(232,160,32,.25);}\n  .dt{display:grid;grid-template-columns:auto 1fr;gap:2px 8px;padding:1px 0;font-variant-numeric:tabular-nums;font-size:10.5px;}\n  .dt .k{color:var(--text-faint);letter-spacing:.05em;}\n  .dt .v{color:var(--text);text-align:right;}\n  .dt .v.ok{color:var(--green);}.dt .v.warn{color:var(--amber-b);}.dt .v.bad{color:var(--red);}.dt .v.dim{color:var(--text-dim);}\n  .sect{font-size:9px;letter-spacing:.2em;text-transform:uppercase;color:var(--amber-d);padding:6px 0 3px;border-bottom:1px dotted var(--amber-fade);margin-bottom:3px;}\n  .sect:first-child{padding-top:0;}\n  #mainBody{font-size:11.5px;line-height:1.6;}\n  .ln{white-space:pre-wrap;word-break:break-word;}\n  .ln.sys{color:var(--amber);}.ln.inf{color:var(--text-dim);}.ln.ok{color:var(--green);}\n  .ln.warn{color:var(--amber-b);}.ln.bad{color:var(--red);}.ln.cmd{color:#fff;font-weight:500;}\n  .ln.t{color:var(--red);font-weight:700;letter-spacing:.1em;}.ln.sub{color:var(--text-faint);padding-left:3ch;}\n  #codeBody{font-size:10.5px;line-height:1.45;font-variant-numeric:tabular-nums;}\n  .cln{white-space:pre;color:#a88c50;}.cln.cm{color:var(--text-faint);}\n  #nodeGrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(46px,1fr));gap:6px 4px;padding:2px;}\n  .uav{display:flex;flex-direction:column;align-items:center;gap:1px;transition:all .3s;padding:2px 0;}\n  .uav svg{width:34px;height:34px;transition:filter .3s,opacity .3s;filter:drop-shadow(0 0 3px rgba(224,80,48,.6));}\n  .uav .id{font-size:7.5px;color:var(--text-faint);letter-spacing:.05em;transition:color .3s;}\n  .uav .st{font-size:6.5px;letter-spacing:.05em;color:var(--red);transition:color .3s;}\n  .uav.done svg{filter:drop-shadow(0 0 6px rgba(184,200,64,.8));}\n  .uav.done .id{color:var(--green);}.uav.done .st{color:var(--green);}\n  .uav.writing svg{animation:uavPulse .5s infinite alternate;filter:drop-shadow(0 0 7px rgba(255,192,67,1));}\n  @keyframes uavPulse{from{opacity:.4}to{opacity:1}}\n  #hud-bot{display:flex;align-items:center;gap:12px;padding:0 10px;background:linear-gradient(180deg,#0d0a06,#050403);border:1px solid var(--amber-d);font-size:9.5px;letter-spacing:.15em;text-transform:uppercase;color:var(--text-dim);font-variant-numeric:tabular-nums;}\n  #hud-bot .item b{color:var(--amber);font-weight:400;}\n  #hud-bot .spacer{flex:1;}\n  #hud-bot .prog{flex:0 0 220px;height:8px;background:#050403;border:1px solid var(--amber-d);position:relative;overflow:hidden;}\n  #hud-bot .prog .fill{height:100%;width:0%;background:linear-gradient(90deg,var(--amber-d),var(--amber-b));box-shadow:0 0 8px var(--amber-fade);transition:width .15s linear;}\n  #hud-bot .pct{color:var(--amber);font-weight:400;}\n  #dim{position:fixed;inset:0;z-index:400;background:rgba(0,0,0,.15);opacity:0;pointer-events:none;transition:opacity .4s;}\n  #dim.show{opacity:1;}\n  .win-popup{position:fixed;z-index:500;min-width:640px;max-width:min(980px,94vw);background:var(--bg-win);border:1px solid var(--amber-d);box-shadow:0 24px 70px rgba(0,0,0,.78),0 0 0 1px rgba(0,0,0,.9),0 0 50px rgba(232,160,32,.1),inset 0 0 24px rgba(232,160,32,.02);opacity:0;transform:scale(.9) translateY(-6px);transition:opacity .22s ease, transform .22s cubic-bezier(.2,1.05,.4,1);overflow:hidden;pointer-events:none;}\n  .win-popup.show{opacity:1;transform:scale(1) translateY(0);pointer-events:auto;}\n  .win-popup.closing{opacity:0;transform:scale(.94) translateY(-4px);}\n  .win-popup.danger{border-color:var(--red);box-shadow:0 24px 70px rgba(0,0,0,.85),0 0 0 1px rgba(0,0,0,.9),0 0 60px rgba(224,80,48,.22),inset 0 0 24px rgba(224,80,48,.03);}\n  .win-popup.info{border-color:var(--cyan);box-shadow:0 24px 70px rgba(0,0,0,.78),0 0 0 1px rgba(0,0,0,.9),0 0 50px rgba(79,209,197,.14);}\n  .wp-title{display:flex;align-items:center;gap:8px;padding:8px 14px;background:linear-gradient(180deg,#1a1208,#0e0a06);border-bottom:1px solid var(--amber-d);font-size:12px;letter-spacing:.12em;color:var(--amber);user-select:none;}\n  .win-popup.danger .wp-title{background:linear-gradient(180deg,#2a0e08,#150805);border-bottom-color:rgba(224,80,48,.6);color:var(--red-b);}\n  .win-popup.info .wp-title{background:linear-gradient(180deg,#08201c,#051210);border-bottom-color:rgba(79,209,197,.5);color:var(--cyan);}\n  .wp-title .wp-ico{width:14px;height:14px;flex:none;display:flex;align-items:center;justify-content:center;font-size:11px;}\n  .wp-title .wp-name{flex:1;font-weight:500;letter-spacing:.16em;text-transform:uppercase;}\n  .wp-title .wp-controls{display:flex;gap:2px;}\n  .wp-title .wp-btn{width:20px;height:18px;display:flex;align-items:center;justify-content:center;font-size:11px;color:var(--text-dim);border:1px solid transparent;cursor:default;transition:all .15s;}\n  .wp-title .wp-btn:hover{background:rgba(232,160,32,.15);color:var(--amber-b);border-color:var(--amber-d);}\n  .win-popup.danger .wp-btn:hover{background:rgba(224,80,48,.2);color:var(--red-b);border-color:rgba(224,80,48,.5);}\n  .wp-body{padding:18px 22px;font-size:13px;line-height:1.65;color:var(--text);max-height:56vh;overflow:auto;}\n  .wp-body::-webkit-scrollbar{width:6px;}\n  .wp-body::-webkit-scrollbar-thumb{background:rgba(232,160,32,.25);}\n  .wp-row{display:grid;grid-template-columns:auto 1fr;gap:8px 22px;padding:6px 0;font-size:12.5px;font-variant-numeric:tabular-nums;border-bottom:1px dotted rgba(232,160,32,.12);}\n  .wp-row:last-child{border-bottom:none;}\n  .wp-row .k{color:var(--text-faint);letter-spacing:.08em;text-transform:uppercase;font-size:11px;}\n  .wp-row .v{color:var(--text);text-align:right;letter-spacing:.02em;}\n  .wp-row .v.ok{color:var(--green);}.wp-row .v.warn{color:var(--amber-b);}.wp-row .v.bad{color:var(--red);}\n  .wp-div{height:1px;margin:12px 0;background:linear-gradient(90deg,transparent,var(--amber-fade),transparent);}\n  .wp-note{margin-top:14px;padding:10px 14px;background:rgba(232,160,32,.06);border-left:3px solid var(--amber);color:var(--amber-b);font-size:12px;line-height:1.65;}\n  .win-popup.danger .wp-note{background:rgba(224,80,48,.08);border-left-color:var(--red);color:#f0b090;}\n  .wp-log{background:#040302;border:1px solid var(--text-faint);padding:10px 12px;max-height:150px;overflow-y:auto;font-size:11.5px;line-height:1.6;color:var(--text-dim);}\n  .wp-log::-webkit-scrollbar{width:5px;}\n  .wp-log::-webkit-scrollbar-thumb{background:rgba(232,160,32,.2);}\n  .wp-log .ll{white-space:pre-wrap;word-break:break-word;}\n  .wp-log .ll.ok{color:var(--green);}.wp-log .ll.warn{color:var(--amber-b);}.wp-log .ll.bad{color:var(--red);}.wp-log .ll.hl{color:var(--amber);}\n  .wp-prog{height:8px;background:#040302;border:1px solid var(--text-faint);position:relative;overflow:hidden;margin:8px 0;}\n  .wp-prog .f{height:100%;width:0%;background:linear-gradient(90deg,var(--amber-d),var(--amber-b));box-shadow:0 0 8px var(--amber-fade);transition:width .2s linear;}\n  .win-popup.danger .wp-prog .f{background:linear-gradient(90deg,#8a2010,var(--red-b));box-shadow:0 0 8px rgba(224,80,48,.5);}\n  .wp-btns{display:flex;gap:8px;margin-top:16px;justify-content:flex-end;}\n  .wp-btn-b{padding:6px 20px;background:linear-gradient(180deg,#1a1208,#0a0805);border:1px solid var(--amber-d);color:var(--amber);font-family:inherit;font-size:12px;letter-spacing:.15em;text-transform:uppercase;cursor:default;transition:all .15s;}\n  .wp-btn-b:hover{background:rgba(232,160,32,.15);border-color:var(--amber);color:var(--amber-b);box-shadow:0 0 14px rgba(232,160,32,.22);}\n  .wp-btn-b.primary{background:linear-gradient(180deg,#3a2408,#1a1005);border-color:var(--amber);color:var(--amber-b);}\n  .wp-btn-b.primary:hover{background:rgba(232,160,32,.25);box-shadow:0 0 18px rgba(232,160,32,.42);}\n  .win-popup.danger .wp-btn-b{border-color:rgba(224,80,48,.6);color:var(--red-b);}\n  .win-popup.danger .wp-btn-b:hover{background:rgba(224,80,48,.2);border-color:var(--red);box-shadow:0 0 14px rgba(224,80,48,.4);}\n  .win-popup.danger .wp-btn-b.primary{background:linear-gradient(180deg,#3a0e08,#1a0505);border-color:var(--red);color:#ffb090;}\n  .win-popup.danger .wp-btn-b.primary:hover{background:rgba(224,80,48,.35);box-shadow:0 0 22px rgba(224,80,48,.6);}\n  .wp-status{display:flex;align-items:center;gap:10px;padding:6px 14px;background:linear-gradient(180deg,#0e0a06,#080604);border-top:1px solid var(--amber-d);font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--text-faint);font-variant-numeric:tabular-nums;}\n  .win-popup.danger .wp-status{border-top-color:rgba(224,80,48,.4);}\n  .wp-status .spacer{flex:1;}\n  .wp-alert-strip{height:2px;width:100%;background:repeating-linear-gradient(90deg,var(--red) 0 10px, transparent 10px 20px);animation:alertMove 1s linear infinite;}\n  @keyframes alertMove{from{background-position:0 0;}to{background-position:20px 0;}}\n  .wp-meter{display:flex;align-items:baseline;gap:10px;padding:8px 0;font-variant-numeric:tabular-nums;}\n  .wp-meter .big{font-size:34px;color:var(--amber-b);letter-spacing:.02em;text-shadow:0 0 14px rgba(232,160,32,.5);}\n  .wp-meter .unit{font-size:12px;color:var(--text-dim);letter-spacing:.06em;text-transform:uppercase;}\n  .win-popup.danger .wp-meter .big{color:var(--red-b);text-shadow:0 0 14px rgba(224,80,48,.6);}\n  .wp-wave{display:flex;align-items:flex-end;gap:1px;height:44px;padding:4px;background:#040302;border:1px solid var(--text-faint);}\n  .wp-wave i{flex:1;background:linear-gradient(180deg,var(--amber),var(--amber-d));height:10%;transition:height .1s linear;}\n  #final{position:fixed;left:50%;top:50%;transform:translate(-50%,-50%);z-index:800;padding:52px 110px;background:#0a0805;border-top:1px solid var(--amber);border-bottom:1px solid var(--amber);box-shadow:0 0 80px rgba(232,160,32,.55),0 0 180px rgba(232,160,32,.22),inset 0 0 80px rgba(232,160,32,.08);color:var(--amber-b);font-size:clamp(30px,4.4vw,58px);letter-spacing:.26em;text-align:center;text-shadow:0 0 14px rgba(232,160,32,.95),0 0 40px rgba(232,160,32,.6);white-space:nowrap;font-weight:500;clip-path:inset(0 50% 0 50%);opacity:0;transition:clip-path .48s cubic-bezier(.7,0,.2,1), opacity .2s ease;}\n  #final.show{opacity:1;clip-path:inset(0 0 0 0);}\n  #final::before,#final::after{content:\"\";position:absolute;top:-2px;bottom:-2px;width:2px;background:var(--amber-b);box-shadow:0 0 20px 4px rgba(232,160,32,.9);opacity:0;pointer-events:none;}\n  #final::before{left:50%;}#final::after{right:50%;}\n  #final.show::before{animation:edgeLeft .48s cubic-bezier(.7,0,.2,1) forwards;}\n  #final.show::after{animation:edgeRight .48s cubic-bezier(.7,0,.2,1) forwards;}\n  @keyframes edgeLeft{0%{left:50%;opacity:1;}90%{left:0;opacity:1;}100%{left:0;opacity:0;}}\n  @keyframes edgeRight{0%{right:50%;opacity:1;}90%{right:0;opacity:1;}100%{right:0;opacity:0;}}\n  #hint{position:fixed;left:0;right:0;bottom:8px;z-index:700;text-align:center;font-size:10px;letter-spacing:.25em;color:var(--text-faint);opacity:0;transition:opacity .6s;pointer-events:none;text-transform:uppercase;}\n  #hint.show{opacity:.7;}\n\n  /* ===== 开头：DeepSeek 字标的自我书写（描边 → 填充 → 辉光）===== */\n  .boot-stage{flex-direction:column;}\n  .boot-aura{position:absolute;left:50%;top:50%;width:64vw;height:44vh;max-width:48rem;transform:translate(-50%,-50%);border-radius:9999px;background:#3b82f6;opacity:.12;filter:blur(120px);pointer-events:none;}\n  #logo text{font-family:\"Orbitron\",\"Exo 2\",\"Segoe UI Variable Display\",\"Segoe UI\",system-ui,-apple-system,\"Noto Sans SC\",\"Microsoft YaHei\",sans-serif;font-size:138px;font-weight:700;letter-spacing:0;}\n  .glyph{fill:#3b82f6;stroke:#3b82f6;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;paint-order:stroke fill;stroke-dasharray:1100;stroke-dashoffset:1100;fill-opacity:0;}\n  .boot-stage.writing .glyph{animation:draw-outline .48s cubic-bezier(.22,.61,.36,1) forwards,fill-letter .34s cubic-bezier(.22,.61,.36,1) .12s forwards;}\n  .boot-stage.writing .glyph-2{animation-delay:.10s,.22s;}\n  .boot-stage.writing .glyph-3{animation-delay:.20s,.32s;}\n  .boot-stage.writing .glyph-4{animation-delay:.30s,.42s;}\n  .boot-stage.writing .glyph-5{animation-delay:.40s,.52s;}\n  .boot-stage.writing .glyph-6{animation-delay:.50s,.62s;}\n  .boot-stage.writing .glyph-7{animation-delay:.60s,.72s;}\n  .boot-stage.writing .glyph-8{animation-delay:.70s,.82s;}\n  @keyframes draw-outline{from{stroke-dashoffset:1100;}to{stroke-dashoffset:0;}}\n  @keyframes fill-letter{0%{fill-opacity:.03;filter:drop-shadow(0 0 0 rgba(59,130,246,0));}55%{fill-opacity:.76;filter:drop-shadow(0 0 10px rgba(59,130,246,.45));}100%{fill-opacity:1;filter:drop-shadow(0 0 5px rgba(59,130,246,.35));}}\n  @keyframes fade-in-up{from{opacity:0;transform:translateY(10px);}to{opacity:1;transform:translateY(0);}}\n  #tagline{margin-top:clamp(22px,3.2vh,34px);padding-left:.4em;color:transparent;background:linear-gradient(180deg,#aab6c6 0%,#8b9aaf 52%,#748399 100%);-webkit-background-clip:text;background-clip:text;font-family:\"Noto Sans SC\",\"Microsoft YaHei\",sans-serif;font-size:clamp(12px,1.45vw,15px);font-weight:500;line-height:1.6;letter-spacing:.4em;white-space:nowrap;opacity:0;}\n  .boot-stage.writing #tagline{animation:fade-in-up .8s cubic-bezier(.22,.61,.36,1) 1.35s forwards;}\n\n  /* ===== 结尾视频（SYSTEM IS REWRITTEN 之后）===== */\n  .finale{position:fixed;inset:0;z-index:3000;display:flex;align-items:center;justify-content:center;background:#000;opacity:0;transition:opacity .5s ease;pointer-events:none;}\n  .finale.show{opacity:1;}\n  .finale-video{display:block;width:100%;height:100%;object-fit:cover;}\n";

